with d as (select value r from jsonb_array_elements($q$[{"notes":["Use the best beef you can find, this dish lives or dies by the meat. Ask your butcher for a thick-cut rib eye on the bone, minimum 4 cm.","A txuleta is not about technique. It's about respecting good meat and not mucking it about.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Take the txuleta out of the fridge 30 minutes before cooking so it comes to room temperature."},{"text":"Get your grill smoking hot, charcoal if you can, or a cast-iron griddle over high heat if you can't."},{"text":"Pat the meat dry. Season both sides generously with salt when it hits the grill, which should be smoking hot so the meat sizzles on contact."},{"text":"Grill for 5–6 minutes on the first side without moving it. You want a dark crust."},{"text":"Flip once. Grill for another 4–5 minutes for medium-rare (around 52°C inside). A thick chop like this needs time; don't rush it."},{"text":"Rest on a warm plate for 3–4 minutes. Crack pepper over the top and serve."}],"id":"6b920162-dbe8-42b7-8006-ed84ea452afb"},{"notes":["Make it ahead: cook the rice the morning before and reheat gently with a splash of water in a covered pot. The flavours deepen overnight.","Serve alongside rendang, grilled chicken, or slow-cooked beef, whatever you have time for."],"steps":[{"text":"Heat the oil in a large heavy-based pot over medium heat. Add the garlic and cook, stirring, until fragrant, about 1 minute."},{"text":"Add the turmeric, cumin seeds, cloves, and cinnamon stick. Toast, stirring gently, for 2–3 minutes until the spices smell rich and the seeds start to pop."},{"text":"Pour in the coconut milk and chicken stock, then add the lemongrass stalks. Stir well and bring to a gentle simmer until the liquid is steaming and lightly bubbling and the kitchen smells fragrant."},{"text":"Add the rinsed rice and salt. Stir once to combine, then reduce the heat to low. Cover with a tight-fitting lid."},{"text":"Cook without lifting the lid for 18–20 minutes, until the rice is tender and all the liquid has been absorbed."},{"text":"Remove from the heat and let it rest, covered, for 5 minutes. Fluff gently with a fork, discard the lemongrass stalks and cinnamon stick, then scatter spring onions over the top if you like."}],"id":"5c690272-269f-4137-96af-7d528f12dcf3"},{"notes":["The marinade also works on pork shoulder, beef or cauliflower. Cook times will vary.","If you don't have time to marinate overnight, 4 hours is the minimum, but the flavour won't be as deep.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Blend the spring onions, Scotch bonnets, garlic, ginger, thyme, allspice, black pepper, salt, olive oil, soy sauce and lime juice in a food processor until you have a thick, textured paste. Taste it, it should make you sit up straight."},{"text":"Rub the jerk paste all over the chicken, working it into the skin and under any flaps you can lift. Put the chicken in a bowl, cover, and refrigerate overnight (or at least 6 hours, though overnight is better)."},{"text":"Take the chicken out of the fridge 30 minutes before cooking so it comes to room temperature."},{"text":"Heat a large cast-iron or heavy-based pan over medium-high heat until it's very hot, or preheat your grill to high. Lightly oil the pan or grill grates."},{"text":"Working in batches if needed so you don't crowd the pan, place the chicken skin-side down. Don't move it for 6–8 minutes until the skin is charred and sticky. You want some blackened edges."},{"text":"Turn the chicken and cook for another 8–10 minutes on the other side until cooked through (the thickest part of the thigh should reach 75°C inside, or the juices run clear when pierced with a knife). If the outside is colouring too fast, lower the heat slightly."},{"text":"Rest the chicken for 5 minutes, then serve hot with rice and peas, or with a simple salad and lime wedges."}],"id":"e815035b-ce93-4266-8649-7894e5ff4d7b"},{"steps":[{"text":"Rinse the rice and moong dal together under cold water until the water runs clear."},{"text":"Heat the ghee in a large saucepan over a medium heat. Add the cumin seeds and dried red chilli, and let them crackle for about 30 seconds."},{"text":"Add the asafoetida and stir for a few seconds until fragrant, then add the rinsed rice and dal, stirring to coat in the ghee for about 2 minutes."},{"text":"Add the turmeric and salt, stir, then add the water and bring to a boil until the water is bubbling steadily."},{"text":"Add the diced carrot and other vegetables, stir well, then reduce the heat to low, cover with a lid and cook for about 12–15 minutes, until the rice and dal are tender and the water is absorbed."},{"text":"Stir through gently with a fork to fluff, taste and adjust the salt if needed. Serve hot."}],"id":"16c48655-7ad6-4d1b-9f80-0c8089c3545a"},{"notes":["Fa'ausi keeps in the fridge for 2 days and reheats gently in a covered dish at 160°C for 15 minutes.","You can prep the parcels several hours ahead and refrigerate them before baking, add 10 minutes to the cooking time."],"steps":[{"text":"Preheat oven to 180°C. Prepare banana leaves by briefly wiping with a damp cloth and cutting into 30 cm squares, you'll need about 6 pieces."},{"text":"In a bowl, combine taro chunks, sliced onion, salt and white pepper. Divide the mixture among the banana leaf squares, spooning about 150 ml coconut cream over each portion."},{"text":"Fold the banana leaves over the filling to make neat parcels, tucking the edges underneath. Place seam-side down on a large baking tray."},{"text":"Bake for 45 to 50 minutes, until the taro is very tender when pierced with a fork and the coconut cream is bubbling gently at the edges."},{"text":"Remove from oven and let rest for 5 minutes. Unwrap carefully, the steam inside is very hot, and serve straight from the banana leaf."}],"id":"ad4968ea-9b7b-4df9-b2a5-ecaee92fd774"},{"notes":["Make it ahead: cool and refrigerate for up to 2 days, then reheat gently on the stove with a splash of water if the glaze has set. The flavours deepen overnight.","No mirin? Use 1 tbsp more caster sugar instead, though you'll lose a bit of the subtle sweetness.","Serve with steamed rice or over kimchi and rice for something richer.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"94788142-266e-4a5a-a16c-249569e95f76"},{"notes":["Chimichurri lasts 3 days in an airtight jar in the fridge, though the parsley will darken slightly.","Make it fresh the day you need it if you can. Inés never makes it more than a few hours ahead.","Serve with grilled beef, chicken, or even crusty bread, it's not just for meat, though that's what Inés says it's for."],"steps":[{"text":"Finely chop the parsley, not in a food processor, by hand with a sharp knife. This matters."},{"text":"Mince the garlic very fine; Inés says you should be able to see each piece."},{"text":"In a bowl, combine the parsley, garlic, and red wine vinegar. Let it sit for 2 minutes so the vinegar softens the parsley."},{"text":"Slowly pour in the olive oil while stirring until the sauce is glossy and just slightly emulsified, so it stays bright and fresh, not heavy."},{"text":"Taste and season with salt and black pepper. If you like, add the oregano and chilli flakes, but Inés says this is between you and your conscience."},{"text":"Let it rest for at least 10 minutes before serving so the flavours marry. Serve at room temperature with grilled meat, bread, or anything that needs the taste of home."}],"id":"d5871f23-7aca-4ffa-9cde-561150f18fb1"},{"notes":["Make ahead: shape the rings, let them rise, then freeze for up to 3 weeks. Bake directly from frozen, adding 5 minutes to the bake time.","The molasses dip is key, it makes the sesame stick like glue. Don't skip it or use water alone."],"id":"d1566244-de0b-4fb3-9f0e-f5bc2b19779b"},{"notes":["If you can't find taro root, use potato or yam, either works well and cooks in about the same time.","This dish is even better the next day: cover and store in the fridge, then reheat gently in a 160°C oven for 15 minutes with a splash of water."],"id":"95ae6be2-1f58-4b38-a7ef-e264af1ec32a"},{"notes":["A tagine pot keeps the braise gentle and even, but a wide shallow pan works just as well.","This is equally good made a few hours ahead and gently reheated before serving.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the olive oil in a large tagine or heavy-based pan over medium heat. Add the onion and cook, stirring gently, until soft and translucent, about 5 minutes."},{"text":"Add the garlic, ginger, turmeric and cinnamon. Stir for 1 minute until fragrant."},{"text":"Pour in the stock and bring to a gentle simmer until the liquid is bubbling lightly. Add the preserved lemon and olives, and season lightly with salt and pepper."},{"text":"Nestle the fish fillets into the liquid, skin-side up if they have skin. Simmer gently for 12–15 minutes, until the fish is cooked through and flakes easily when tested with a fork."},{"text":"Taste and adjust seasoning. Scatter with fresh coriander if you like, and serve straight from the tagine with couscous or crusty bread."}],"id":"901cda7a-60f9-47b9-bf08-bee1630a1090"},{"notes":["Use a good, spicy harissa here, it's not a garnish, it's the whole point.","Make sure the eggs go into a shallow pan so the yolks stay runny while the whites cook through.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"a740f631-2765-4a67-9fb8-ad3ef555c3dc"},{"steps":[{"text":"Cook the egg noodles in salted boiling water until tender, about 8 minutes. Drain well and set aside."},{"text":"While the noodles cook, melt the butter in a large heavy-bottomed pan over medium heat. Add the sliced onions and cook, stirring often, until they're soft and deeply golden, about 12 minutes. This is where the flavour happens, don't rush it."},{"text":"Add the sliced cabbage to the pan with the caramelized onions. Stir to coat with butter. Cook, stirring occasionally, until the cabbage is very soft and golden at the edges, about 8 minutes."},{"text":"Tip the cooked noodles into the pan with the cabbage and onions. Toss everything together until well combined. Season with salt and pepper to taste."},{"text":"Divide among bowls and top with crispy fried onions or fried shallots if you like the crunch, they're optional, but they add something special."}],"id":"ff993685-c628-4790-9e67-b0af817a0040"},{"notes":["Make ahead: cook the dashimaki tamago the night before, wrap in cling film and refrigerate. It's fine cold or at room temperature.","No tamagoyaki pan? A regular non-stick frying pan works, but you'll get a circular roll instead of rectangular slices.","If you can't find instant dashi, use 60 ml water mixed with a tiny pinch of salt and bonito flakes instead.","Food safety: The eggs are cooked until just set. For pregnant women, young children, older people or anyone with a weakened immune system, cook them until firm all the way through."],"id":"f2e46263-0c65-4fc8-88a8-ca6641b50f12"},{"notes":["Swap the green beans for whatever green veg you have: broccolini, bok choy, snap peas or zucchini all work.","Use fresh prawns if you have them, they'll cook in about 2 minutes instead of 3–4.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Heat 2 tbsp coconut milk in a large pan over medium-high heat. Stir in the curry paste and cook for 1 minute until fragrant."},{"text":"Pour in the remaining coconut milk and stock, stirring to combine. Bring to a simmer until the curry is bubbling gently and fragrant."},{"text":"Add the green beans and cook for 5 minutes until just tender."},{"text":"Add the frozen prawns and cook, stirring occasionally, for 3–4 minutes until they're pink and cooked through."},{"text":"Stir in the fish sauce, lime juice and sugar. Taste and adjust the seasoning, add more fish sauce or lime to taste."},{"text":"Serve over steamed jasmine rice with fresh Thai basil or coriander if you have it."}],"id":"406589de-902d-40bd-9a71-41968edf373a"},{"notes":["Cook and cool the rice ahead, leftover rice works best. You want it cold and separate so it fries properly.","If clams are very sandy, soak them in salted water for 30 minutes before cooking to help them expel grit.","Fried shallots can be made several hours ahead and stored in an airtight container.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through. Throw away any mussels or clams whose shells stay closed after cooking. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"925217e4-5afe-4a26-9868-395e5c9a3982"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;